// Competitions, truly end to end: the REAL Apps Script code (apps-script/
// Comp*.gs on the fake world, tests/fakes) builds and publishes through the
// real admin API, and the REAL public engine (competition/<slug>/ stub as
// generated by the publish, comp.json, content.json, media — all served
// from the FakeGitHub commit over the repo files) talks to the real public
// actions in a real browser. The site's Date header and the server's
// clock are the world's clock (world.advance moves both).
//
// Phase 2/3 (registered mode, the wallet, «نقاطي» and the store) at the end.
//
// Run: cd tools && node --test ../tests/comp-live.e2e.mjs

import test from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { createRequire } from 'node:module';
import { existsSync, readFileSync, statSync } from 'node:fs';
import { extname, join, normalize } from 'node:path';
import { ROOT } from '../tools/lib/gs.mjs';
import { PUSH_CONFIG } from '../assets/js/push-config.js';
import { FakeGitHub } from './fakes/gas.mjs';
import { compWorld, adminApi, publish, scoredComp, wallAt, SITE } from './fakes/comp.mjs';

const require = createRequire(`${ROOT}tools/package.json`);
const puppeteer = require('puppeteer-core');

const PORT = 4963;
const BASE = `http://localhost:${PORT}`;
const API = PUSH_CONFIG.apiUrl;
const CHROME = [
  'C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
  '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  '/usr/bin/google-chrome'
].find(existsSync);

const PHONE = { width: 390, height: 844, isMobile: true, hasTouch: true, deviceScaleFactor: 1 };
const SHELL = readFileSync(`${ROOT}competition/index.html`, 'utf8');
const SITE_CSP = /<meta http-equiv="Content-Security-Policy" content="([^"]+)">/.exec(readFileSync(`${ROOT}index.html`, 'utf8'))[1];
const TYPES = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.json': 'application/json; charset=utf-8', '.webp': 'image/webp', '.jpg': 'image/jpeg', '.png': 'image/png', '.woff2': 'font/woff2', '.webmanifest': 'application/manifest+json', '.ics': 'text/calendar' };
const PRIVATE = /^\/(apps-script|tools|tests|docs|node_modules)(\/|$)|\/\.|\.md$/i;


/* =========================================================
   WORLD + SITE
========================================================= */

let world = null;      // the world the site and the API belong to right now
let served = [];
let server;
let browser;

/** a fresh world with the real engine shell committed (stubs are made from it) */
function newWorld() {
  world = compWorld({ github: new FakeGitHub({ files: { 'competition/index.html': SHELL } }) });
  served = [];
  return { world, call: adminApi(world) };
}

/** what GitHub Pages would serve now: the last commit over the repo's files */
function committed(path) {
  const files = world ? world.github.files() : {};
  const key = path.replace(/^\//, '');
  const value = files[key.endsWith('/') || key === '' ? `${key}index.html` : key];
  return value === undefined ? null : Buffer.isBuffer(value) ? value : Buffer.from(String(value), 'utf8');
}

test.before(async () => {
  server = createServer((req, res) => {
    const path = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    const headers = { 'Cache-Control': 'no-store', Date: new Date(world ? world.now() : Date.now()).toUTCString() };
    const send = (status, type, body) => {
      served.push({ path, status });
      res.writeHead(status, { ...headers, 'Content-Type': type });
      res.end(body);
    };
    const file = path.endsWith('/') ? `${path}index.html` : path;
    const fromCommit = committed(file);
    if (fromCommit) return send(200, TYPES[extname(file)] || 'application/octet-stream', fromCommit);
    try {
      if (PRIVATE.test(path)) throw new Error('private');
      const local = normalize(join(ROOT, file));
      if (!local.startsWith(normalize(ROOT)) || !statSync(local).isFile()) throw new Error('no');
      return send(200, TYPES[extname(local)] || 'application/octet-stream', readFileSync(local));
    }
    catch {
      return send(404, 'text/plain', '404');
    }
  });
  await new Promise(resolve => server.listen(PORT, '127.0.0.1', resolve));
  browser = await puppeteer.launch({ executablePath: CHROME, headless: true });
});

test.after(async () => {
  await browser?.close();
  server?.close();
});


/* =========================================================
   BROWSER (the Apps Script URL → world.post, like Apps Script: 302 → echo)
========================================================= */

async function open(path, { hook = null } = {}) {

  const context = await browser.createBrowserContext();
  const page = await context.newPage();
  const problems = [];
  const replies = [];
  const outside = [];
  const echoes = new Map();
  let echo = 0;

  page.on('console', msg => { if (msg.type() === 'error' && /CSP|Content Security|Refused/i.test(msg.text())) problems.push(msg.text()); });
  page.on('pageerror', error => problems.push(`pageerror: ${error.message}`));
  await page.evaluateOnNewDocument(() => document.addEventListener('securitypolicyviolation', e => console.error(`CSP violation: ${e.violatedDirective} ${e.blockedURI}`)));
  await page.emulateMediaFeatures([{ name: 'prefers-reduced-motion', value: 'reduce' }]);
  await page.setViewport(PHONE);
  await page.setRequestInterception(true);
  page.on('request', request => {
    const url = request.url();
    if (url === API && request.method() === 'POST') {
      const body = request.postData() || '{}';
      const { fn, args } = JSON.parse(body);
      const reply = world.post(body);
      delete reply.mime;
      replies.push({ fn, arg: args[0], reply, text: JSON.stringify(reply) });
      // hook may drop the answer AFTER the server did the work (a lost reply)
      if (hook && hook({ fn, arg: args[0], reply }) === 'drop') return request.abort('failed');
      const key = `k${++echo}`;
      echoes.set(key, JSON.stringify(reply));
      return request.respond({ status: 302, headers: { Location: `https://script.googleusercontent.com/macros/echo?user_content_key=${key}`, 'Access-Control-Allow-Origin': '*' }, body: '' });
    }
    if (url.startsWith('https://script.googleusercontent.com/macros/echo?')) {
      return request.respond({ status: 200, contentType: 'application/json; charset=utf-8', headers: { 'Access-Control-Allow-Origin': '*' }, body: echoes.get(new URL(url).searchParams.get('user_content_key')) || '{}' });
    }
    if (/^(https?:\/\/(localhost|127\.0\.0\.1)[:/]|data:|blob:|about:)/.test(url)) return request.continue();
    if (!url.endsWith('/v1/account/config')) outside.push(url);
    return request.respond({ status: 204, body: '' });
  });
  await page.goto(BASE + path, { waitUntil: 'networkidle0' });

  const fns = name => replies.filter(r => r.fn === name);
  return { context, page, problems, replies, outside, fns };

}

const stateOf = page => page.$eval('#comp-main', m => m.dataset.state);
const waitState = (page, name, timeout = 10000) => page.waitForFunction(n => document.getElementById('comp-main')?.dataset.state === n, { timeout }, name);
const textOf = (page, selector) => page.$eval(selector, el => el.textContent.trim());
const clickText = (page, selector, words) => page.evaluate((s, w) => {
  const el = [...document.querySelectorAll(s)].find(e => e.textContent.trim() === w || e.textContent.includes(w));
  if (!el) throw new Error(`no ${s} with ${w}`);
  el.click();
}, selector, words);
const reload = page => page.reload({ waitUntil: 'networkidle0' });

let phones = 100;
const nextPhone = () => `0101234${String(++phones).padStart(4, '0')}`;

async function fillIdentity(page, phone = nextPhone(), name = 'مشترك تجربة') {
  await waitState(page, 'identity');
  await page.type('#f-name', name);
  if (await page.$('#f-phone')) await page.type('#f-phone', phone);
  await page.click('button[type="submit"]');
  return phone;
}

/** the right answers of scoredComp, by question text (works with any served order) */
const RIGHT = {
  'مين بنى الفلك؟': { pick: ['نوح'] },
  'اختار الأناجيل': { pick: ['متى', 'مرقس'] },
  'داود قتل جليات': { pick: ['صح'] },
  'اسم أول سفر؟': { type: 'سفر التكوين' },
  'كام سفر في العهد الجديد؟': { type: '٢٧' }
};

/** answers every paged question (long: `long` text or skipped), arrives at the review */
async function answerAll(page, { long = '', extra = {} } = {}) {
  const plan = { ...RIGHT, ...extra };
  for (let guard = 0; guard < 40; guard += 1) {
    const state = await stateOf(page);
    if (state === 'review') return;
    if (state !== 'question') { await sleep(100); continue; }
    const { text, qid } = await page.$eval('#comp-main [data-q]', q => ({ qid: q.dataset.q, text: q.querySelector('.q__text').textContent.replace('(مطلوب)', '').trim() }));
    const key = Object.keys(plan).find(k => text.startsWith(k));
    const step = key ? plan[key] : null;
    if (step && step.pick) for (const words of step.pick) await page.evaluate((id, w) => [...document.querySelectorAll(`[data-q="${id}"] label.choice`)].find(l => l.textContent.trim() === w).click(), qid, words);
    if (step && step.type) await page.type(`#a-${qid}`, step.type);
    if (!step && long && await page.$(`textarea#a-${qid}`)) await page.type(`#a-${qid}`, long);
    await page.click('[data-next]');
    await page.waitForFunction(old => document.getElementById('comp-main').dataset.state === 'review' || document.querySelector('#comp-main [data-q]')?.dataset.q !== old, {}, qid);
  }
  throw new Error('never reached the review');
}

async function sendFromReview(page) {
  await waitState(page, 'review');
  await page.click('[data-submit]');
  await page.click('[data-confirm]');
  await waitState(page, 'result');
}

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const submissions = (call, id) => call('apiCompSubmissions', id, { status: 'all', limit: 200 });


/* =========================================================
   (a) all 7 types → server-graded result → reload → lost-reply retry; survey
========================================================= */

test('(a) open competition: form, all 7 question types, the server grades, reload shows the result, a lost reply is retried safely', async () => {

  const { call } = newWorld();
  const { id } = scoredComp(call, { slug: 'live-quiz', title: 'مسابقة لايف', resultShow: 'score', answersShow: 'immediately', showPoints: true });
  const survey = call('apiCompCreate', { preset: 'survey', title: 'استبيان لايف', slug: 'live-survey', enabled: true }).comp.id;
  call('apiCompQuestionSave', survey, { type: 'single', text: 'إيه أكتر يوم يناسبك؟', choices: [{ text: 'الجمعة' }, { text: 'السبت' }] });
  call('apiCompQuestionSave', survey, { type: 'long', text: 'اقتراحاتك', required: false });
  publish(world, call);

  let { context, page, problems, fns, outside } = await open('/competition/live-quiz/');
  await waitState(page, 'intro');
  assert.equal(await textOf(page, '.hero__title'), 'مسابقة لايف');
  assert.match(await textOf(page, '.chips'), /٦ أسئلة/);
  await page.click('[data-cta]');
  const phone = await fillIdentity(page);
  await waitState(page, 'question');
  assert.equal(fns('compStart')[0].reply.ok, true);
  assert.equal(await page.$$eval('.q__pts', e => e.length), 1, 'points shown (showPoints)');
  await answerAll(page);
  await sendFromReview(page);
  await page.waitForSelector('.result__line--score');
  assert.equal(await textOf(page, '.result__line--score'), 'جبت ٣٥ من ٤٥', 'graded by the server (the optional long one unanswered)');
  assert.equal(await page.$$eval('.answer', e => e.length), 6, 'review list (answersShow immediately)');
  const list = submissions(call, id);
  assert.equal(list.total, 1);
  assert.equal(list.items[0].status, 'graded');
  assert.equal(list.items[0].score, 35);
  assert.equal(list.items[0].phone.replace(/\D/g, '').slice(-10), phone.slice(-10));

  // reopening: the result from the receipt (compResult), nothing sent again
  await reload(page);
  await page.waitForSelector('.result__line--score');
  assert.equal(fns('compResult').length, 1);
  assert.equal(fns('compResult')[0].reply.ok, true);
  assert.equal(fns('compSubmit').length, 1);
  assert.equal(await page.$('[data-cta]'), null);
  assert.deepEqual(problems, []);
  assert.deepEqual(outside, []);
  await context.close();

  // a submit whose reply is lost: the page retries with the same keys, the server replays
  let dropped = false;
  ({ context, page, problems, fns } = await open('/competition/live-quiz/', { hook: ({ fn }) => (fn === 'compSubmit' && !dropped ? (dropped = true, 'drop') : null) }));
  await page.click('[data-cta]');
  await fillIdentity(page);
  await answerAll(page);
  await sendFromReview(page);
  await page.waitForSelector('.result__line--score', { timeout: 15000 });
  const sends = fns('compSubmit');
  assert.equal(sends.length, 2, 'the lost one and the retry');
  assert.deepEqual(sends[0].arg, sends[1].arg);
  assert.equal(sends[1].reply.receipt, sends[0].reply.receipt, 'the stored result, replayed');
  assert.equal(submissions(call, id).total, 2, 'one submission for that person');
  assert.deepEqual(problems, []);
  await context.close();

  // survey: no score, just thanks
  ({ context, page, problems } = await open('/competition/live-survey/'));
  await page.click('[data-cta]');
  await fillIdentity(page);
  await waitState(page, 'question');
  await clickText(page, 'label.choice', 'السبت');
  await page.click('[data-next]');
  await page.click('[data-next]');
  await sendFromReview(page);
  assert.equal(await page.$('.result__line--score'), null);
  assert.equal(await page.$('.answers'), null);
  assert.match(await textOf(page, '.result__title'), /وصلت/);
  assert.equal(submissions(call, survey).items[0].status, 'submitted');
  assert.deepEqual(problems, []);
  await context.close();

});


/* =========================================================
   (b) answers after the close
========================================================= */

test('(b) answersShow afterClose: no answers before the end; after it, reopening shows the review list', async () => {

  const { call } = newWorld();
  scoredComp(call, { slug: 'after-close', endAt: wallAt(world, 30), answersShow: 'afterClose' });
  publish(world, call);

  const { context, page, problems, fns } = await open('/competition/after-close/');
  await page.click('[data-cta]');
  await fillIdentity(page);
  await answerAll(page);
  await sendFromReview(page);
  await page.waitForSelector('.result__line--score');
  assert.equal(await page.$('.answers'), null, 'no review before the close');
  assert.match(await textOf(page, '.result__lines'), /الإجابات الصحيحة هتظهر/);

  world.advance(40 * 60000);
  await reload(page);
  await page.waitForSelector('.answers');
  assert.equal(await page.$$eval('.answer', e => e.length), 6);
  assert.equal(await page.$$eval('.answer--ok', e => e.length), 5);
  assert.ok(fns('compResult').at(-1).reply.result.review);
  assert.deepEqual(problems, []);
  await context.close();

});


/* =========================================================
   (c) scheduled → open; «اقفل دلوقتي»
========================================================= */

test('(c) a future competition counts down, opens with the world clock; «اقفل دلوقتي» refuses new starts', async () => {

  const { call } = newWorld();
  const { id } = scoredComp(call, { slug: 'soon-quiz', startAt: wallAt(world, 120), endAt: wallAt(world, 2000) });
  publish(world, call);

  const { context, page, problems, fns } = await open('/competition/soon-quiz/');
  await waitState(page, 'scheduled');
  assert.equal(await textOf(page, '[data-countdown]'), 'تبدأ بعد ساعتين');
  assert.equal(await page.$('[data-cta]'), null);

  world.advance(121 * 60000);
  await reload(page);
  await waitState(page, 'intro');
  assert.ok(await page.$('[data-cta]'));

  call('apiCompClose', id);
  await page.click('[data-cta]');
  await fillIdentity(page);
  await waitState(page, 'closed');
  assert.equal(fns('compStart')[0].reply.code, 'closed');
  assert.match(await textOf(page, '.alert'), /خلصت/);
  assert.deepEqual(problems, []);
  await context.close();

});


/* =========================================================
   (d) time limit
========================================================= */

test('(d) time limit: the world clock runs out, the page submits by itself, the server accepts', async () => {

  const { call } = newWorld();
  const { id } = scoredComp(call, { slug: 'timed-quiz', timeLimit: 1 });
  publish(world, call);

  const { context, page, problems, fns } = await open('/competition/timed-quiz/');
  await page.click('[data-cta]');
  await fillIdentity(page);
  await waitState(page, 'question');
  await page.waitForSelector('#comp-timer:not([hidden])');
  assert.match(await textOf(page, '#comp-timer'), /٠١:٠٠|٠٠:٥\d/);
  const start = fns('compStart')[0].reply.attempt;
  assert.equal(start.deadlineMs - start.serverNow, 60000);
  await clickText(page, 'label.choice', 'نوح');

  // 55 s pass on the server; the reopened page reads the clock from the site's Date header
  world.advance(55000);
  await reload(page);
  await waitState(page, 'question');
  await page.waitForFunction(() => document.getElementById('comp-timer').classList.contains('is-low'));
  await waitState(page, 'result', 15000);
  const sent = fns('compSubmit');
  assert.equal(sent.length, 1, 'sent without a tap');
  assert.equal(sent[0].reply.ok, true);
  assert.equal(Object.keys(sent[0].arg.answers).length, 1);
  assert.equal(submissions(call, id).items[0].status, 'graded');
  assert.deepEqual(problems, []);
  await context.close();

});


